    $parentBefore=$fresh.ParentSnapshotId.ToString('D');Need ([guid]$parentBefore -eq $parent) 'OFF lineage differs.';$before=@(Get-VMSnapshot -VM (Get-VM -Id $id));Need ($before.Count -eq 50 -and @($old|Where-Object {$_ -notin @($before.Id|ForEach-Object {$_.ToString('D')})}).Count -eq 0 -and @($before|Where-Object Name -CEQ $snapshotName).Count -eq 0) 'All50/new checkpoint name required.'
    Save 'partial-checkpoint-create-intent.json' @{vm_id=$id.ToString();run_id=$run;name=$snapshotName;parent_before_creation=$parentBefore;prior_checkpoint_ids=$old;creation_issued_at_most_once=$true;utc=[DateTime]::UtcNow.ToString('o')};$created=Checkpoint-VM -VM (Get-VM -Id $id) -SnapshotName $snapshotName -Passthru -ErrorAction Stop;$direct=if($null -ne $created -and [guid]$created.Id -ne [guid]::Empty){$created.Id.ToString('D')}else{$null};$deadline=[DateTime]::UtcNow.AddSeconds(30)
    do{$fresh=Get-VM -Id $id;$all=@(Get-VMSnapshot -VM $fresh);$match=@($all|Where-Object Name -CEQ $snapshotName);Need ($match.Count -le 1) 'Duplicate partial checkpoint name.';if($match.Count -eq 1 -and $all.Count -eq 51 -and @($old|Where-Object {$_ -notin @($all.Id|ForEach-Object {$_.ToString('D')})}).Count -eq 0){$cp=$match[0].Id.ToString('D');Need (($null -eq $direct -or $cp -ceq $direct) -and $cp -notin $old -and $fresh.State.ToString() -ceq 'Off' -and $fresh.MemoryAssigned -eq 0) 'Fresh checkpoint/OFF identity differs.';break};if([DateTime]::UtcNow -ge $deadline){throw 'Fresh snapshot view did not settle within30s; never retry creation.'};Start-Sleep -Milliseconds 500}while($true)
    Save 'partial-checkpoint.json' @{success=$true;run_id=$run;vm_id=$id.ToString();checkpoint_id=$cp;parent_id=$parentBefore;checkpoint_count=51;all_prior50_preserved=$true;state='Off';memory_assigned=0;controlled_interruption_observed=$true;conversion_success=$false;native_exit_observed=$true;native_exit=86;interrupt_after_writes=1;metadata_pins_sha256=(Get-FileHash -LiteralPath (Join-Path $root 'partial-metadata-pins.json')).Hash.ToLowerInvariant();source_offline=$true;source_readonly=$false;shadow_offline=$true;shadow_readonly=$true;source_journal_packed_vhdx_raw_opened=$false;journal_marker_observed=$false;handoff_closed_claimed=$false;raw_recovery_authorized=$false;scope=$record.scope;utc=[DateTime]::UtcNow.ToString('o')};Get-Content -LiteralPath (Join-Path $root 'partial-checkpoint.json') -Raw
}catch{if($intentSaved -and -not(Test-Path -LiteralPath (Join-Path $root 'preservation-failed.json'))){Save 'preservation-failed.json' @{success=$false;run_id=$run;error=$_.Exception.ToString();automatic_retry=$false;checkpoint_creation_repeated=$false;utc=[DateTime]::UtcNow.ToString('o')}};throw}
finally{if($null -ne $session){Remove-PSSession $session}}
